-- Demo data for trying airadminer locally.
DROP SCHEMA IF EXISTS shop CASCADE;
CREATE SCHEMA shop;
CREATE TYPE shop.order_status AS ENUM ('draft','paid','shipped','delivered','refunded');

CREATE TABLE shop.customers (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email       text NOT NULL UNIQUE,
  full_name   text NOT NULL,
  country     char(2),
  vip         boolean NOT NULL DEFAULT false,
  signed_up   timestamptz NOT NULL DEFAULT now(),
  tags        text[],
  profile     jsonb,
  external_id uuid DEFAULT gen_random_uuid()
);
COMMENT ON TABLE shop.customers IS 'People who bought something';
COMMENT ON COLUMN shop.customers.vip IS 'Gets free shipping';

CREATE TABLE shop.products (
  sku        text PRIMARY KEY,
  title      text NOT NULL,
  price      numeric(10,2) NOT NULL CHECK (price >= 0),
  stock      integer NOT NULL DEFAULT 0,
  released   date,
  notes      text,
  thumbnail  bytea
);

CREATE TABLE shop.orders (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id bigint NOT NULL REFERENCES shop.customers(id),
  status      shop.order_status NOT NULL DEFAULT 'draft',
  total       numeric(12,2),
  placed_at   timestamptz DEFAULT now(),
  ship_window tstzrange,
  note        text
);
CREATE INDEX orders_customer_idx ON shop.orders(customer_id);

CREATE TABLE shop.order_items (
  order_id bigint REFERENCES shop.orders(id) ON DELETE CASCADE,
  sku      text REFERENCES shop.products(sku),
  qty      int NOT NULL DEFAULT 1,
  PRIMARY KEY (order_id, sku)
);

CREATE TABLE public.audit_log (ts timestamptz DEFAULT now(), actor text, action text, payload json);

INSERT INTO shop.customers (email, full_name, country, vip, signed_up, tags, profile)
SELECT 'user' || g || '@example.com',
       (ARRAY['Ada','Grace','Linus','Margaret','Ken','Barbara','Edsger','Frances','Dennis','Radia'])[1 + g % 10] || ' ' ||
       (ARRAY['Lovelace','Hopper','Torvalds','Hamilton','Thompson','Liskov','Dijkstra','Allen','Ritchie','Perlman'])[1 + (g * 7) % 10],
       (ARRAY['US','DE','FR','JP','BR','IN','GB','CA',NULL])[1 + g % 9],
       g % 7 = 0,
       now() - (g || ' hours')::interval * 13,
       CASE WHEN g % 3 = 0 THEN ARRAY['beta','newsletter'] WHEN g % 5 = 0 THEN ARRAY['wholesale'] END,
       jsonb_build_object('plan', (ARRAY['free','pro','team'])[1 + g % 3], 'seats', g % 12, 'theme', CASE WHEN g % 2 = 0 THEN 'dark' ELSE 'light' END)
FROM generate_series(1, 2500) g;

