INSERT INTO shop.orders (customer_id, status, total, placed_at, ship_window, note)
SELECT 1 + (g * 37) % 2500,
       (ARRAY['draft','paid','shipped','delivered','refunded'])[1 + g % 5]::shop.order_status,
       round((random() * 900 + 10)::numeric, 2),
       now() - (g || ' minutes')::interval * 41,
       tstzrange(now() + interval '1 day', now() + interval '4 days'),
       CASE WHEN g % 11 = 0 THEN 'Leave at the door' END
FROM generate_series(1, 20000) g;

INSERT INTO shop.order_items SELECT o, (ARRAY['KB-01','MS-02','MN-27','CB-10'])[1 + o % 4], 1 + o % 3 FROM generate_series(1, 20000) o;
INSERT INTO public.audit_log (actor, action, payload) VALUES ('system','seed','{"rows": 20000}');
CREATE VIEW shop.vip_customers AS SELECT id, email, full_name, country FROM shop.customers WHERE vip;
ANALYZE;
